#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}


# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────
#
# Newsletter setup: everything the newsletter needs in Resend and on Railway.
#
#   bash apps/questura/infra/newsletter/setup-newsletter.sh
#
# Resend and Railway are changed through their APIs with keys already in the
# owner's vault (RESEND_SETUP_KEY, full access; RAILWAY_API_TOKEN). New values
# are saved to the vault and then copied to the questura-server service. No
# value is ever printed. Safe to re-run: each stage reuses what exists.
# What each variable does: apps/questura/apps/server/src/features/newsletter/lib/config.ts
# GraphQL variables ($i) live in single-quoted query strings on purpose.
# shellcheck disable=SC2016

ENV_FILE="${QUESTURA_VAULT_ENV:-$HOME/.questura-vault/owner.env}"
RESEND=https://api.resend.com
RAILWAY=https://backboard.railway.com/graphql/v2
PROJECT_ID=aa5759b2-a793-4f16-8e8b-8633cdc41cac
ENVIRONMENT_ID=e35f0d85-c66d-4f66-b781-d9e456bab8cb
SERVER_SERVICE_ID=0f920c5a-3d07-4a51-a75a-fd7a29726f86
SEGMENT_NAME="Questurian newsletter"
KEY_NAME="questura-newsletter"
WEBHOOK_URL="https://api.questurian.com/api/newsletter/webhook"
WEBHOOK_EVENTS='["contact.updated","contact.deleted","email.bounced","email.complained","email.suppressed"]'
REPO_ROOT=$(cd "$(dirname "$0")/../../../.." && pwd)

for tool in curl jq; do
  command -v "$tool" >/dev/null || { echo "missing tool: $tool" >&2; exit 2; }
done
[[ -r "$ENV_FILE" ]] || { echo "cannot read $ENV_FILE" >&2; exit 2; }

WORK=$(mktemp -d); chmod 700 "$WORK"; trap 'rm -rf "$WORK"' EXIT
vault() { _existing "$1" | sed -e 's/^"//' -e 's/"$//'; }
printf 'Authorization: Bearer %s\n' "$(vault RESEND_SETUP_KEY)" > "$WORK/resend-auth"
printf 'Authorization: Bearer %s\n' "$(vault RAILWAY_API_TOKEN)" > "$WORK/railway-auth"

# resend METHOD PATH [JSON]: response body on stdout; stops on an HTTP error.
resend() {
  local code
  code=$(curl -sS --max-time 30 -o "$WORK/out" -w '%{http_code}' -X "$1" "$RESEND$2" \
    -H "@$WORK/resend-auth" -H 'Content-Type: application/json' ${3:+--data-binary "$3"})
  if [[ "$code" != 2* ]]; then
    printf '  %sResend answered %s on %s %s: %s%s\n' "$RED" "$code" "$1" "$2" "$(jq -r '.message // .name // "?"' "$WORK/out" 2>/dev/null)" "$RESET" >&2
    exit 1
  fi
  cat "$WORK/out"
}

TOTAL_STAGES=6

banner "Questurian newsletter setup (Resend + Railway)"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Resend: the newsletter segment"
say "Every confirmed subscriber is copied into one Resend segment, and every issue goes to it."
SEGMENT_ID=$(resend GET /segments | jq -r --arg n "$SEGMENT_NAME" '[.data[] | select(.name == $n)][0].id // empty')
if [[ -n "$SEGMENT_ID" ]]; then
  note "Found \"$SEGMENT_NAME\" already."
else
  confirm "Create the segment \"$SEGMENT_NAME\" in Resend?" || { warn "stopped"; exit 1; }
  SEGMENT_ID=$(resend POST /segments "$(jq -n --arg n "$SEGMENT_NAME" '{name:$n}')" | jq -r '.id')
fi
write_env RESEND_NEWSLETTER_SEGMENT_ID "$SEGMENT_ID"
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Resend: an API key for the newsletter"
say "Sending an issue needs a full-access key. It is kept apart from the"
say "password-reset key so either can be revoked without touching the other."
if [[ -n "$(vault RESEND_NEWSLETTER_API_KEY)" ]]; then
  note "The vault already has RESEND_NEWSLETTER_API_KEY; keeping it."
else
  confirm "Create the full-access key \"$KEY_NAME\" in Resend?" || { warn "stopped"; exit 1; }
  NEW_KEY=$(resend POST /api-keys "$(jq -n --arg n "$KEY_NAME" '{name:$n, permission:"full_access"}')" | jq -r '.token')
  write_env RESEND_NEWSLETTER_API_KEY "$NEW_KEY"
  unset NEW_KEY
fi
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "Resend: the webhook back to the site"
say "Resend tells the site when a reader unsubscribes from an issue, an"
say "address bounces, or someone marks an issue as spam."
WEBHOOK_ID=$(resend GET /webhooks | jq -r --arg u "$WEBHOOK_URL" '[.data[] | select(.endpoint == $u)][0].id // empty')
if [[ -n "$WEBHOOK_ID" ]]; then
  note "Found the webhook to $WEBHOOK_URL already."
  SECRET=$(resend GET "/webhooks/$WEBHOOK_ID" | jq -r '.signing_secret')
else
  confirm "Create a webhook to $WEBHOOK_URL?" || { warn "stopped"; exit 1; }
  SECRET=$(resend POST /webhooks "$(jq -n --arg u "$WEBHOOK_URL" --argjson e "$WEBHOOK_EVENTS" '{endpoint:$u, events:$e}')" | jq -r '.signing_secret')
fi
write_env RESEND_WEBHOOK_SECRET "$SECRET"
unset SECRET
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "The postal address in every issue's footer"
say "US law (CAN-SPAM) requires a real postal address in every newsletter."
say "A PO box or virtual mailbox is fine. The site will not send an issue"
say "to the list until this is set; previews and test sends work without it."
note "No address yet? Press Enter to skip, and run this wizard again once you have one."
ask NEWSLETTER_POSTAL_ADDRESS "Postal address (one line):"
NEWSLETTER_POSTAL_ADDRESS=$(printf '%s' "$NEWSLETTER_POSTAL_ADDRESS" | sed -e 's/^"//' -e 's/"$//')
if [[ -n "${NEWSLETTER_POSTAL_ADDRESS:-}" ]]; then
  # Quoted: an address has spaces and commas, and the vault is a dotenv file.
  write_env NEWSLETTER_POSTAL_ADDRESS "\"${NEWSLETTER_POSTAL_ADDRESS//\"/}\""
else
  SKIPPED+=("NEWSLETTER_POSTAL_ADDRESS: get a PO box, then re-run this wizard")
fi
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Railway: give the values to questura-server"
say "Copies the newsletter values from the vault to the live API's variables."
say "Railway then redeploys questura-server on its current code (about 3 minutes)."
jq -n \
  --arg k "$(vault RESEND_NEWSLETTER_API_KEY)" \
  --arg s "$(vault RESEND_NEWSLETTER_SEGMENT_ID)" \
  --arg w "$(vault RESEND_WEBHOOK_SECRET)" \
  --arg a "$(vault NEWSLETTER_POSTAL_ADDRESS)" \
  '{RESEND_NEWSLETTER_API_KEY:$k, RESEND_NEWSLETTER_SEGMENT_ID:$s, RESEND_WEBHOOK_SECRET:$w}
   + (if $a == "" then {} else {NEWSLETTER_POSTAL_ADDRESS:$a} end)' > "$WORK/vars.json"
note "Setting: $(jq -r 'keys | join(", ")' "$WORK/vars.json")"
if confirm "Set these on questura-server and redeploy it?"; then
  body=$(jq -n --arg p "$PROJECT_ID" --arg e "$ENVIRONMENT_ID" --arg s "$SERVER_SERVICE_ID" --slurpfile v "$WORK/vars.json" \
    '{query:"mutation($i:VariableCollectionUpsertInput!){ variableCollectionUpsert(input:$i) }",
      variables:{i:{projectId:$p, environmentId:$e, serviceId:$s, variables:$v[0], replace:false}}}')
  response=$(curl -sS --max-time 60 "$RAILWAY" -H "@$WORK/railway-auth" -H 'Content-Type: application/json' --data-binary "$body")
  if jq -e '.errors' <<<"$response" >/dev/null 2>&1; then
    printf '  %sRailway API error: %s%s\n' "$RED" "$(jq -c '[.errors[].message]' <<<"$response")" "$RESET"; exit 1
  fi
  printf '  %s✓ set%s on questura-server\n' "$GREEN" "$RESET"
  say "Bringing the nightly reconcile cron's variable list in line (it mirrors the server's)."
  bash "$REPO_ROOT/apps/questura/infra/railway/create-reconcile-cron.sh" --apply || \
    SKIPPED+=("reconcile cron: run apps/questura/infra/railway/create-reconcile-cron.sh --apply")
else
  SKIPPED+=("Railway variables on questura-server: re-run this wizard")
fi
pause

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Check the live site picked them up"
say "Waiting for questura-server to come back with the webhook switched on..."
say "(An unsigned test call should be refused as 400 \"Invalid signature\", not 503.)"
ok=""
for _ in $(seq 1 40); do
  code=$(curl -s -o /dev/null -w '%{http_code}' -X POST "$WEBHOOK_URL" -H 'Content-Type: application/json' --data '{}') || true
  if [[ "$code" == "400" ]]; then ok=1; break; fi
  sleep 15
done
if [[ -n "$ok" ]]; then
  printf '  %s✓ the live webhook is on%s\n' "$GREEN" "$RESET"
  say "Open Studio → Newsletter: the yellow \"not ready\" box should be gone"
  say "(or list only NEWSLETTER_POSTAL_ADDRESS if you skipped it)."
else
  SKIPPED+=("the live webhook still answers $code after 10 minutes: check Railway → questura-server → Deployments")
fi
pause

finish
